css:
  /* Estilo general para ajustar el tamaño a media carta */
  @page {
    size: 8.5in 5.5in; /* Media carta */
    margin: 0.5in; /* Márgenes */
  }

  body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    line-height: 1.5;
  }

.header {
  width: 100%; /* Hace que el header ocupe todo el ancho */
  margin-bottom: 10px; /* Espacio inferior */
  border-bottom: 3px solid #000000; /* Línea inferior */
}

.header table {
  width: 100%; /* La tabla ocupa todo el ancho */
  border-collapse: collapse; /* Elimina espacios entre celdas */
}

.header td {
  text-align: center; /* Centra el contenido horizontalmente */
  vertical-align: middle; /* Centra el contenido verticalmente */
}

.header .imagen {
  height: 80px; /* Altura específica para la imagen */
  width: auto; /* Mantiene la proporción de la imagen */
  margin-bottom: 5px; /* Espaciado debajo del logo */
}

.membrete {
  font-family: Arial, sans-serif; /* Tipo de letra */
  font-size: 10px; /* Tamaño pequeño */
  font-weight: bold; /* Texto en negrita */
  text-transform: uppercase; /* Texto en mayúsculas */
  line-height: 1; /* Entrelineado pegado */
  margin: 0;
}

.title {
  font-size: 14px;
  font-weight: bold;
  text-transform: uppercase;
  margin-top: 10px;
}


  .info {
  width: 60%; /* Hace que la tabla ocupe todo el contenedor */
  margin: 0 auto; /* Centra la tabla horizontalmente */
  border-collapse: collapse; /* Elimina cualquier espacio entre celdas */
}

.info td {
  width: 50%; /* Cada celda ocupa el 50% del espacio */
  padding: 2px 8px; /* Espaciado interno ajustado (vertical mínimo) */
  text-align: left; /* Alinea el texto a la izquierda */
  vertical-align: top; /* Alineación vertical al inicio */
  font-size: 14px; /* Tamaño de letra */
  line-height: 0.4; /* Espaciado entre líneas casi nulo */
}
 

.info tr {
  margin: 0; /* Elimina cualquier margen adicional */
  padding: 0; /* Elimina cualquier relleno adicional */
}

.info .alinear {
  text-align: right;  
}


.info strong {
  font-weight: bold; /* Negrita para el texto dentro de las celdas */
}


  .signature {
    width: 50%;
    text-align: center;
    margin-top: 40px;
    font-weight: bold;
    border-top: 2px solid #000000;
    margin-left:auto;
    margin-right:auto;
  }

  .qr-section {
    display: flex;
    justify-content: center;
    align-items: center;
    margin: 10px 0;
  }

  .seal {
    position: absolute;
    bottom: 50px;
    left: 30px;
    opacity: 0.5;
  }

  .data-section {
    width: 100%;
    margin-top: 20px;
  }

  .data-section td {
    border: none;
    padding: 4px;
  }
  
  .membrete {
  font-family: Arial, sans-serif; /* Tipo de letra simple y claro */
  font-size: 10px; /* Tamaño pequeño */
  font-weight: bold; /* Texto en negrita */
  text-transform: uppercase; /* Convierte todo el texto a mayúsculas */
  line-height: 1; /* Entrelineado pegado */
  margin: 0; /* Elimina márgenes adicionales */
  text-align: center; /* Centra el texto horizontalmente */
}


.text-red {
  color: #FF0000; /* Rojo puro en hexadecimal */
}

.signature-section {
    position: relative; /* Contenedor relativo para usar position absoluta en la imagen */
    margin-top: 30px;
    text-align: center;
}

.signature-image img {
    width: 100px; /* Ajusta el tamaño de la imagen */
    height: auto; /* Mantiene proporciones */
    position: absolute;
    right: 40%; /* Ajusta el desplazamiento hacia la derecha (puedes cambiar el valor) */
    top: -80px; /* Ajusta la distancia hacia arriba desde la firma */
}

.signature {
    width: 50%; /* Ajusta el ancho del texto de la firma */
    text-align: center; /* Centra el texto */
    font-weight: bold; /* Texto en negrita */
    border-top: 2px solid #000000; /* Línea superior para la firma */
    margin: 0 auto; /* Centra horizontalmente la firma */
    padding-top: 10px; /* Espacio entre la línea y el texto */
}
